begin;
create function pg_temp.crm_assert(ok boolean,label text) returns void language plpgsql as $$ begin if not coalesce(ok,false) then raise exception 'CRM QA failed: %',label; end if; end $$;
do $$
declare
 u1 uuid='99990000-0000-4000-8000-000000000001'; u2 uuid='99990000-0000-4000-8000-000000000002'; u3 uuid='99990000-0000-4000-8000-000000000003'; u4 uuid='99990000-0000-4000-8000-000000000004'; u5 uuid='99990000-0000-4000-8000-000000000005'; u6 uuid='99990000-0000-4000-8000-000000000006'; u7 uuid='99990000-0000-4000-8000-000000000007'; u8 uuid='99990000-0000-4000-8000-000000000008'; u9 uuid='99990000-0000-4000-8000-000000000009';
 fa uuid; fb uuid; ha uuid; hb uuid; hc uuid; note_id uuid; task_id uuid; sim_id uuid; archive_id uuid; link_id uuid; request_id uuid=gen_random_uuid(); payload jsonb; result jsonb; twice jsonb; blocked boolean; n integer; source_doc text;
begin
 perform pg_temp.crm_assert(not exists(select 1 from auth.users where id in(u1,u2,u3,u4,u5,u6,u7,u8,u9)),'QA IDs must not overlap real users');
 insert into auth.users(id,email,raw_user_meta_data) values
 (u1,'crm-qa-owner@example.invalid','{"name":"QA Owner"}'),(u2,'crm-qa-advisor@example.invalid','{"name":"QA Advisor"}'),(u3,'crm-qa-staff@example.invalid','{"name":"QA Staff"}'),(u4,'crm-qa-outsider@example.invalid','{"name":"QA Outside Firm"}'),(u5,'crm-qa-supervisor@example.invalid','{"name":"QA Supervisor"}'),(u6,'crm-qa-unassigned@example.invalid','{"name":"QA Unassigned"}'),(u7,'crm-qa-disabled@example.invalid','{"name":"QA Disabled"}'),(u8,'crm-qa-invitee@example.invalid','{"name":"QA Invitee"}'),(u9,'crm-qa-expired@example.invalid','{"name":"QA Expired"}');
 fa=(public.crm_dispatch(u1,null,'firm.create','{"name":"QA rollback firm A","is_demo":false}',gen_random_uuid())->>'id')::uuid;
 fb=(public.crm_dispatch(u4,null,'firm.create','{"name":"QA rollback firm B","is_demo":false}',gen_random_uuid())->>'id')::uuid;
 perform set_config('app.crm_actor',u1::text,true);
 insert into public.crm_members(firm_id,user_id,name,email,role,status) values(fa,u2,'QA Advisor','crm-qa-advisor@example.invalid','advisor','active'),(fa,u3,'QA Staff','crm-qa-staff@example.invalid','staff','active'),(fa,u5,'QA Supervisor','crm-qa-supervisor@example.invalid','supervisor','active'),(fa,u6,'QA Unassigned','crm-qa-unassigned@example.invalid','staff','active'),(fa,u7,'QA Disabled','crm-qa-disabled@example.invalid','staff','disabled');
 ha=(public.crm_dispatch(u1,fa,'household.create',jsonb_build_object('name','QA Household A','stage','active','service_tier','Core','lead_advisor_id',u2,'member_ids',jsonb_build_array(u3),'review_due','2026-11-06','summary','QA only'),gen_random_uuid())->>'id')::uuid;
 hb=(public.crm_dispatch(u1,fa,'household.create',jsonb_build_object('name','QA Household B','stage','active','service_tier','Core','lead_advisor_id',u2,'member_ids','[]'::jsonb,'summary','QA only'),gen_random_uuid())->>'id')::uuid;
 hc=(public.crm_dispatch(u4,fb,'household.create',jsonb_build_object('name','QA Other Firm Household','stage','active','service_tier','Core','lead_advisor_id',u4,'member_ids','[]'::jsonb,'summary','QA only'),gen_random_uuid())->>'id')::uuid;
 perform pg_temp.crm_assert(public.crm_actor_can_household(fa,ha,u2),'Assigned advisor can access household');
 perform pg_temp.crm_assert(public.crm_actor_can_household(fa,ha,u3),'Assigned staff can access household');
 perform pg_temp.crm_assert(not public.crm_actor_can_household(fa,hb,u3),'Unassigned household is hidden from staff');
 perform pg_temp.crm_assert(not public.crm_actor_can_household(fa,ha,u6),'Unassigned staff cannot access');
 perform pg_temp.crm_assert(not public.crm_actor_can_household(fa,ha,u7),'Disabled staff cannot access');
 perform pg_temp.crm_assert(not public.crm_actor_can_household(fa,ha,u4),'Other firm owner cannot access');
 perform pg_temp.crm_assert(public.crm_actor_can_household(fa,hb,u5),'Supervisor can access firm households');
 blocked=false; begin perform public.crm_dispatch(u3,fa,'household.update',jsonb_build_object('id',ha,'version',1),gen_random_uuid()); exception when others then blocked=sqlerrm='CRM_FORBIDDEN'; end;
 perform pg_temp.crm_assert(blocked,'Staff cannot change household team access');
 payload=jsonb_build_object('household_id',ha,'title','QA meeting','occurred_at','2026-10-30T15:00:00Z','attendees','Fictional QA people','discussion','Synthetic meeting discussion for transactional testing only.','decisions','No client decision or recommendation.','followups',jsonb_build_array(jsonb_build_object('title','QA follow-up','assigned_to',u2,'due_on','2026-11-06','priority','normal')));
 result=public.crm_dispatch(u3,fa,'meeting.create',payload,request_id); note_id=(result->>'id')::uuid;
 twice=public.crm_dispatch(u3,fa,'meeting.create',payload,request_id);
 perform pg_temp.crm_assert(result=twice,'Idempotent retry returns original meeting');
 perform pg_temp.crm_assert((select count(*)=1 from public.crm_meetings where id=note_id),'Only one meeting after retry');
 perform pg_temp.crm_assert((select count(*)=1 from public.crm_tasks where meeting_id=note_id),'Only one follow-up after retry');
 select id into task_id from public.crm_tasks where meeting_id=note_id;
 blocked=false; begin perform public.crm_dispatch(u3,fa,'meeting.create',payload||'{"title":"Changed payload"}',request_id); exception when others then blocked=sqlerrm='CRM_CONFLICT'; end;
 perform pg_temp.crm_assert(blocked,'Idempotency key cannot be reused with changed payload');
 n=(select count(*) from public.crm_meetings where firm_id=fa);
 blocked=false; begin perform public.crm_dispatch(u3,fa,'meeting.create',payload||jsonb_build_object('followups',jsonb_build_array(jsonb_build_object('title','Forbidden assignee','assigned_to',u6,'priority','normal'))),gen_random_uuid()); exception when others then blocked=position('household access' in sqlerrm)>0; end;
 perform pg_temp.crm_assert(blocked and (select count(*)=n from public.crm_meetings where firm_id=fa),'Invalid follow-up rolls back its meeting');
 payload=jsonb_build_object('id',task_id,'version',1,'title','QA follow-up','details','QA only','assigned_to',u2,'due_on','2026-11-06','priority','high','status','done');
 perform public.crm_dispatch(u3,fa,'task.update',payload,gen_random_uuid());
 perform pg_temp.crm_assert((select status='done' and completed_at is not null and version=2 from public.crm_tasks where id=task_id),'Task completion saved and attributed');
 blocked=false; begin perform public.crm_dispatch(u3,fa,'task.update',payload,gen_random_uuid()); exception when others then blocked=sqlerrm='CRM_CONFLICT'; end;
 perform pg_temp.crm_assert(blocked,'Stale task update rejected');
 perform public.crm_dispatch(u3,fa,'meeting.finalize',jsonb_build_object('id',note_id,'version',1,'confirmed',true),gen_random_uuid());
 blocked=false; begin update public.crm_meetings set discussion='tamper' where id=note_id; exception when others then blocked=position('cannot be edited' in sqlerrm)>0; end;
 perform pg_temp.crm_assert(blocked,'Database rejects editing a final meeting');
 result=public.crm_dispatch(u3,fa,'meeting.create',jsonb_build_object('household_id',ha,'title','QA amendment','occurred_at','2026-10-30T16:00:00Z','attendees','','discussion','QA correction to a fictional meeting note.','decisions','','supersedes_id',note_id,'followups','[]'::jsonb),gen_random_uuid());
 perform pg_temp.crm_assert((select supersedes_id=note_id and status='draft' from public.crm_meetings where id=(result->>'id')::uuid),'Amendment preserves original final note');
 sim_id=gen_random_uuid();
 insert into public.kyp_simulation_runs(id,owner_id,document) values(sim_id,u1,jsonb_build_object('reportDate','2026-10-16','rows',jsonb_build_array(jsonb_build_object('holding',jsonb_build_object('id','holding-QA','requestedName','QA Product','portfolioHolding',jsonb_build_object('identifier','QA123','clientCount',999,'marketValue',123456789)),'identity','candidate','notes',jsonb_build_object('rationale','PRIVATE_SOURCE_TEXT')))));
 payload=jsonb_build_object('household_id',ha,'source_kind','simulation','source_id',sim_id,'holding_id','holding-QA','assigned_to',u2,'review_notes','QA household context only');
 link_id=(public.crm_dispatch(u1,fa,'kyp.attach',payload,gen_random_uuid())->>'id')::uuid;
 perform pg_temp.crm_assert((select review_status='needs_evidence' and position('PRIVATE_SOURCE_TEXT' in row_to_json(k)::text)=0 and position('clientCount' in row_to_json(k)::text)=0 and position('123456789' in row_to_json(k)::text)=0 from public.crm_kyp_reviews k where id=link_id),'KYP reference excludes private source notes and book totals');
 blocked=false; begin perform public.crm_dispatch(u2,fa,'kyp.attach',payload,gen_random_uuid()); exception when others then blocked=position('Private source holding not found' in sqlerrm)>0; end;
 perform pg_temp.crm_assert(blocked,'Another advisor cannot attach a private source they do not own');
 blocked=false; begin perform public.crm_dispatch(u1,fa,'kyp.update',jsonb_build_object('id',link_id,'version',1,'assigned_to',u2,'review_status','reviewed','review_notes','QA: a draft simulation is not complete evidence.'),gen_random_uuid()); exception when others then blocked=position('archived product record' in sqlerrm)>0; end;
 perform pg_temp.crm_assert(blocked,'Simulation cannot be marked reviewed even by owner');
 archive_id=gen_random_uuid(); source_doc=jsonb_build_object('generatedAt','2026-10-30T15:00:00Z','research',jsonb_build_object('target',jsonb_build_object('name','QA archived product','symbol','QA.TO')),'customNotes','PRIVATE_SOURCE_TEXT')::text;
 insert into public.kyp_review_archive(id,owner_id,kind,document,sha256) values(archive_id,u1,'audit',source_doc,encode(sha256(convert_to(source_doc,'UTF8')),'hex'));
 link_id=(public.crm_dispatch(u1,fa,'kyp.attach',jsonb_build_object('household_id',ha,'source_kind','archive','source_id',archive_id,'assigned_to',u5,'review_notes','QA tracking only'),gen_random_uuid())->>'id')::uuid;
 perform public.crm_dispatch(u5,fa,'kyp.update',jsonb_build_object('id',link_id,'version',1,'assigned_to',u5,'review_status','reviewed','review_notes','QA supervisory review of a synthetic archived product record, not suitability.'),gen_random_uuid());
 blocked=false; begin perform public.crm_dispatch(u3,fa,'kyp.update',jsonb_build_object('id',link_id,'version',2,'assigned_to',u3,'review_status','open','review_notes','Attempted staff reopening'),gen_random_uuid()); exception when others then blocked=sqlerrm='CRM_FORBIDDEN'; end;
 perform pg_temp.crm_assert(blocked,'Staff cannot reopen a supervisory review');
 blocked=false; begin update public.crm_audit_events set action='tamper' where firm_id=fa; exception when others then blocked=position('append-only' in sqlerrm)>0; end;
 perform pg_temp.crm_assert(blocked,'Audit events are append-only');
 perform public.crm_dispatch(u1,fa,'invite.create',jsonb_build_object('email','crm-qa-invitee@example.invalid','role','staff','token_hash',repeat('a',64)),gen_random_uuid());
 blocked=false; begin perform public.crm_accept_invite(u4,repeat('a',64)); exception when others then blocked=position('another email address' in sqlerrm)>0; end;
 perform pg_temp.crm_assert(blocked,'Invite is bound to intended email');
 result=public.crm_accept_invite(u8,repeat('a',64)); twice=public.crm_accept_invite(u8,repeat('a',64));
 perform pg_temp.crm_assert(result=twice and public.crm_actor_role(fa,u8)='staff','Invite acceptance is idempotent with intended role');
 perform pg_temp.crm_assert(not public.crm_actor_can_household(fa,ha,u8),'New staff member has no automatic household access');
 perform public.crm_dispatch(u1,fa,'member.update',jsonb_build_object('user_id',u2,'role','admin','status','active'),gen_random_uuid());
 perform public.crm_dispatch(u2,fa,'invite.create',jsonb_build_object('email','crm-qa-expired@example.invalid','role','staff','token_hash',repeat('b',64)),gen_random_uuid());
 perform public.crm_dispatch(u1,fa,'member.update',jsonb_build_object('user_id',u2,'role','admin','status','disabled'),gen_random_uuid());
 blocked=false; begin perform public.crm_accept_invite(u9,repeat('b',64)); exception when others then blocked=position('issuer is no longer authorized' in sqlerrm)>0; end;
 perform pg_temp.crm_assert(blocked,'Disabled inviter cannot grant access');
 perform pg_temp.crm_assert(not has_function_privilege('authenticated','public.crm_dispatch(uuid,uuid,text,jsonb,uuid)','EXECUTE'),'Clients cannot impersonate server actors');
 perform pg_temp.crm_assert(not has_function_privilege('authenticated','public.crm_actor_can_household(uuid,uuid,uuid)','EXECUTE'),'Clients cannot query access using another actor ID');
 perform set_config('crm.test.firm_a',fa::text,true); perform set_config('crm.test.house_a',ha::text,true);
end $$;
select set_config('request.jwt.claim.sub','99990000-0000-4000-8000-000000000003',true);
set local role authenticated;
select pg_temp.crm_assert((select count(*)=1 from public.crm_firms),'RLS hides other firms');
select pg_temp.crm_assert((select count(*)=1 from public.crm_households),'RLS hides unassigned households and other firms');
select pg_temp.crm_assert((select count(*)=0 from public.crm_invites),'Staff cannot read invitations');
select pg_temp.crm_assert(not has_table_privilege(current_user,'public.crm_households','INSERT') and not has_table_privilege(current_user,'public.crm_tasks','UPDATE'),'Direct client writes denied');
reset role;
select 'passed' as status,'CRM roles, household isolation, atomic notes/followups, idempotency, stale updates, immutable notes, KYP privacy, review sign-off, email-bound invitations and RLS' as checks;
rollback;
